   153  /// Scans back from \p ptr until the start of the previous UTF-8 codepoint.
   154  /// Logically, this is equivalent to `--ptr` in the codepoint space.
   155  /// It could be a regular ASCII character, or a multi-byte encoded character.
   156  /// This function assumes that the input is valid!
   157  inline const char *previousUTF8Start(const char *ptr) {
   158    --ptr;
   159    // If the previous codepoint is ASCII, we are done.
   160    if (!(*ptr & 0x80))
   161      return ptr;
   162    // Scan backwards until we find a leading byte (11xxxxxx)
   163    while ((*ptr & 0xC0) != 0xC0)
   164      --ptr;
   165    return ptr;
   166  }
