   168  /// Decode a sequence of UTF8 encoded bytes into a Unicode codepoint.
   169  /// In case of decoding errors, the provided callback is invoked with an
   170  /// apropriate messsage and UNICODE_REPLACEMENT_CHARACTER is returned.
   171  ///
   172  /// \tparam allowSurrogates when false, values in the surrogate range are
   173  ///     reported as errors
   174  /// \param error callback invoked with an error message
   175  /// \return the codepoint
   176  template <bool allowSurrogates, typename F>
   177  inline uint32_t decodeUTF8(const char *&from, F error) {
   178    if (LLVM_LIKELY((*from & 0x80) == 0)) // Ordinary ASCII?
   179      return *from++;
   180
   181    return _decodeUTF8SlowPath<allowSurrogates>(from, error);
   182  }
