   184  /// Encode a 32-bit value, into UTF16. If the value is a part of a surrogate
   185  /// pair, it is encoded without any conversion.
   186  template <typename OutIt>
   187  inline void encodeUTF16(OutIt &dest, uint32_t cp) {
   188    if (LLVM_LIKELY(cp < 0x10000)) {
   189      *dest = (uint16_t)cp;
   190      ++dest; // Use pre-increment in case this is an iterator.
   191    } else {
   192      assert(cp <= UNICODE_MAX_VALUE && "invalid Unicode value");
   193      cp -= 0x10000;
   194      *dest = UTF16_HIGH_SURROGATE + ((cp >> 10) & 0x3FF);
   195      ++dest;
   196      *dest = UTF16_LOW_SURROGATE + (cp & 0x3FF);
   197      ++dest;
   198    }
   199  }
