   201  /// Decode a UTF-8 sequence, which is assumed to be valid, but may possibly
   202  /// contain explicitly encoded surrogate pairs, into a UTF-16 sequence.
   203  /// \return the updated destination iterator
   204  template <typename OutIt>
   205  inline OutIt convertUTF8WithSurrogatesToUTF16(
   206      OutIt dest,
   207      const char *begin8,
   208      const char *end8) {
   209    while (begin8 < end8)
   210      encodeUTF16(dest, decodeUTF8<true>(begin8, [](const llvh::Twine &) {
   211                    llvm_unreachable("invalid UTF-8");
   212                  }));
   213    return dest;
   214  }
